const open = (yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run);
yield* print('open count', open.length);
const results = [];
for (const task of open) {
  const r = yield* ops['com-example-operation-score']({ title: task.title });
  yield* print('raw result for', task.title, JSON.stringify(r));
  results.push({ task, r });
}

const open = yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run;
const scores = [];
for (const task of open) {
  const score = yield* ops['com-example-operation-score']({ title: task.title });
  Obj.update(task, (t) => { t.priority = score; });
  scores.push({ title: task.title, id: task.id, score });
}
yield* Database.flush();

const verify = yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run;
yield* print('stored', verify.map(t => ({ title: t.title, priority: t.priority })));
scores.sort((a, b) => b.score - a.score);
yield* print('highest', JSON.stringify(scores[0]));

